document.documentElement.classList.add('js');
const motion = matchMedia('(prefers-reduced-motion: reduce)');
const toggle=document.querySelector('.menu-toggle'), mobile=document.querySelector('.mobile-nav');
function closeMenu(){mobile.hidden=true;toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','Abrir menu');toggle.textContent='Menu +'}
toggle.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')!=='true';toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'Fechar menu':'Abrir menu');mobile.hidden=!open;toggle.textContent=open?'Fechar −':'Menu +'});
mobile.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMenu()}});
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));document.querySelector('.project-grid').classList.toggle('filtered',button.dataset.filter!=='todos');document.querySelectorAll('[data-project]').forEach(project=>{project.hidden=button.dataset.filter!=='todos'&&project.dataset.category!==button.dataset.filter;project.classList.add('visible')})}));
const projects={varanda:{title:'Entre dentro e fora',type:'Interiores residenciais',description:'Varanda integrada com luz natural e abertura para o exterior. Fotografia do acervo de projetos do escritório.'},suite:{"title":"Pausa e silêncio","type":"Interiores residenciais","description":"Suíte com paleta clara e mobiliário integrado. Fotografia do acervo de projetos do escritório."},cafe:{"title":"Espaços de encontro","type":"Interiores comerciais","description":"Interior de café com composição de madeira e iluminação. Fotografia do acervo de projetos do escritório."},quarto:{"title":"O lugar do descanso","type":"Interiores residenciais","description":"Quarto com cabeceira em madeira e iluminação acolhedora. Fotografia do acervo de projetos do escritório."},boutique:{"title":"Uma nova experiência","type":"Interiores comerciais","description":"Interior de loja com expositores e mobiliário sob medida. Fotografia do acervo de projetos do escritório."},living:{title:'Entre encontros',type:'Interiores residenciais',description:'Madeira, arte e luz natural se encontram em um ambiente de estar integrado. Fotografias do acervo de projetos do escritório.'},clinica:{title:'O cuidado em cada detalhe',type:'Arquitetura de saúde',description:'Um olhar para o acolhimento por meio da iluminação, dos materiais e da organização do ambiente. Fotografia do acervo do escritório.'},escritorio:{title:'Novas conexões',type:'Interiores corporativos',description:'Luz natural e espaços de trabalho em diálogo. Fotografia do acervo de projetos do escritório.'},loja:{title:'Uma identidade que se habita',type:'Interiores comerciais',description:'A experiência do espaço comercial apresentada por seus materiais, mobiliário e composição. Fotografia do acervo do escritório.'}};
const dialog=document.querySelector('.project-dialog');let lastProject;
document.querySelectorAll('[data-project]').forEach(button=>button.addEventListener('click',()=>{const id=button.dataset.project,data=projects[id];lastProject=button;dialog.querySelector('img').src=`assets/${id}.jpg`;dialog.querySelector('img').alt=button.querySelector('img').alt;dialog.querySelector('h2').textContent=data.title;dialog.querySelector('.eyebrow').textContent=data.type;dialog.querySelector('.dialog-description').textContent=data.description;dialog.showModal();document.body.classList.add('dialog-open')}));
dialog.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
dialog.addEventListener('close',()=>{document.body.classList.remove('dialog-open');lastProject?.focus({preventScroll:true})});
dialog.querySelector('.dialog-contact').addEventListener('click',()=>dialog.close());
document.querySelector('#year').textContent=new Date().getFullYear();
